// Anchor is the date a subscription's billing periods are counted from: the end of its trial when it has one, otherwise
// the day it started.
func Anchor(sub store.Subscription) time.Time {
	if sub.TrialEnd != nil {
		return sub.TrialEnd.UTC()
	}
	return sub.StartedAt.UTC()
}

// PeriodStart returns the start of billing period n (n = 0, 1, 2, ...) of a subscription with the given anchor: n months
// after the anchor for a monthly plan, n years for a yearly one. It keeps the anchor's day of the month and time of day,
// or uses the last day of the month when that month is shorter. The result is in UTC.
func PeriodStart(anchor time.Time, iv store.Interval, n int) time.Time {
	a := anchor.UTC()
	months := n
	if iv == store.Yearly {
		months = 12 * n
	}
	first := time.Date(a.Year(), a.Month()+time.Month(months), 1, a.Hour(), a.Minute(), a.Second(), a.Nanosecond(), time.UTC)
	lastDay := time.Date(first.Year(), first.Month()+1, 0, 0, 0, 0, 0, time.UTC).Day()
	return time.Date(first.Year(), first.Month(), min(a.Day(), lastDay), a.Hour(), a.Minute(), a.Second(), a.Nanosecond(), time.UTC)
}

// PeriodIndex returns the number n of the billing period that starts at or before t, the last one to do so. It is the
// inverse of PeriodStart: PeriodIndex(anchor, iv, PeriodStart(anchor, iv, n)) is n.
func PeriodIndex(anchor time.Time, iv store.Interval, t time.Time) int {
	a, u := anchor.UTC(), t.UTC()
	months := (u.Year()-a.Year())*12 + int(u.Month()-a.Month())
	n := months
	if iv == store.Yearly {
		n = months / 12
	}
	for PeriodStart(a, iv, n).After(u) {
		n--
	}
	for !PeriodStart(a, iv, n+1).After(u) {
		n++
	}
	return n
}

// AddInterval returns t moved forward by one billing interval: a month or a year. Like PeriodStart, it keeps the day of the
// month, or uses the last day of a shorter month.
func AddInterval(t time.Time, iv store.Interval) time.Time {
	return PeriodStart(t, iv, 1)
}

