func TestPeriodStartKeepsTheAnchorDay(t *testing.T) {
	anchor := time.Date(2026, 1, 31, 10, 15, 30, 0, time.UTC)
	want := []time.Time{
		time.Date(2026, 1, 31, 10, 15, 30, 0, time.UTC),
		time.Date(2026, 2, 28, 10, 15, 30, 0, time.UTC),
		time.Date(2026, 3, 31, 10, 15, 30, 0, time.UTC),
		time.Date(2026, 4, 30, 10, 15, 30, 0, time.UTC),
		time.Date(2026, 5, 31, 10, 15, 30, 0, time.UTC),
	}
	for n, w := range want {
		if got := PeriodStart(anchor, store.Monthly, n); !got.Equal(w) {
			t.Errorf("monthly n=%d: %v, want %v", n, got, w)
		}
	}
}

func TestPeriodStartLeapDays(t *testing.T) {
	leap := time.Date(2028, 1, 31, 0, 0, 0, 0, time.UTC)
	if got := PeriodStart(leap, store.Monthly, 1); !got.Equal(time.Date(2028, 2, 29, 0, 0, 0, 0, time.UTC)) {
		t.Errorf("monthly into a leap February: %v", got)
	}
	feb29 := time.Date(2028, 2, 29, 6, 0, 0, 0, time.UTC)
	yearly := map[int]time.Time{
		1: time.Date(2029, 2, 28, 6, 0, 0, 0, time.UTC),
		3: time.Date(2031, 2, 28, 6, 0, 0, 0, time.UTC),
		4: time.Date(2032, 2, 29, 6, 0, 0, 0, time.UTC),
	}
	for n, w := range yearly {
		if got := PeriodStart(feb29, store.Yearly, n); !got.Equal(w) {
			t.Errorf("yearly n=%d: %v, want %v", n, got, w)
		}
	}
}

func TestPeriodIndexInvertsPeriodStart(t *testing.T) {
	anchor := time.Date(2026, 1, 31, 10, 0, 0, 0, time.UTC)
	for n := 0; n < 40; n++ {
		start := PeriodStart(anchor, store.Monthly, n)
		if got := PeriodIndex(anchor, store.Monthly, start); got != n {
			t.Fatalf("PeriodIndex(%v) = %d, want %d", start, got, n)
		}
		if got := PeriodIndex(anchor, store.Monthly, start.Add(-time.Second)); got != n-1 {
			t.Fatalf("PeriodIndex just before %v = %d, want %d", start, got, n-1)
		}
	}
	if got := PeriodIndex(anchor, store.Yearly, time.Date(2030, 2, 28, 0, 0, 0, 0, time.UTC)); got != 3 {
		t.Fatalf("yearly PeriodIndex = %d, want 3", got)
	}
}
