func TestRenewalsKeepTheAnchorDay(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	c := e.CreateCustomer(e.Acme, "Jane", "jane@example.com")
	_, _ = e.Store.UpdateCustomer(e.Acme.ID, c.ID, func(c *store.Customer) error { c.DefaultPaymentMethod = "pm_card_visa"; return nil })
	p := e.CreatePlan(e.Acme, "Team", "USD", "20.00")
	e.Clock.Set(time.Date(2026, 1, 31, 10, 0, 0, 0, time.UTC))
	sub, err := e.Subs.Create(ctx, e.Acme.ID, subscriptions.CreateInput{CustomerID: c.ID, PlanID: p.ID, Quantity: 1})
	if err != nil {
		t.Fatal(err)
	}
	for _, want := range []struct{ start, end time.Time }{
		{time.Date(2026, 2, 28, 10, 0, 0, 0, time.UTC), time.Date(2026, 3, 31, 10, 0, 0, 0, time.UTC)},
		{time.Date(2026, 3, 31, 10, 0, 0, 0, time.UTC), time.Date(2026, 4, 30, 10, 0, 0, 0, time.UTC)},
	} {
		e.Clock.Set(want.start)
		if n, err := e.Subs.RenewDue(ctx); err != nil || n != 1 {
			t.Fatalf("RenewDue = %d, %v", n, err)
		}
		got, _ := e.Store.Subscription(e.Acme.ID, sub.ID)
		if !got.CurrentPeriodStart.Equal(want.start) || !got.CurrentPeriodEnd.Equal(want.end) {
			t.Fatalf("period = %v to %v, want %v to %v", got.CurrentPeriodStart, got.CurrentPeriodEnd, want.start, want.end)
		}
	}
}

func TestLateRenewalCatchesUpEveryPeriod(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	c := e.CreateCustomer(e.Acme, "Jane", "jane@example.com")
	_, _ = e.Store.UpdateCustomer(e.Acme.ID, c.ID, func(c *store.Customer) error { c.DefaultPaymentMethod = "pm_card_visa"; return nil })
	p := e.CreatePlan(e.Acme, "Team", "USD", "20.00")
	e.Clock.Set(time.Date(2026, 1, 31, 10, 0, 0, 0, time.UTC))
	sub, err := e.Subs.Create(ctx, e.Acme.ID, subscriptions.CreateInput{CustomerID: c.ID, PlanID: p.ID, Quantity: 1})
	if err != nil {
		t.Fatal(err)
	}
	// The job did not run for two months: periods Feb 28 to Mar 31 and Mar 31 to Apr 30 are both missed.
	e.Clock.Set(time.Date(2026, 4, 2, 9, 0, 0, 0, time.UTC))
	if n, err := e.Subs.RenewDue(ctx); err != nil || n != 1 {
		t.Fatalf("RenewDue = %d, %v", n, err)
	}
	got, _ := e.Store.Subscription(e.Acme.ID, sub.ID)
	if !got.CurrentPeriodStart.Equal(time.Date(2026, 3, 31, 10, 0, 0, 0, time.UTC)) || !got.CurrentPeriodEnd.Equal(time.Date(2026, 4, 30, 10, 0, 0, 0, time.UTC)) {
		t.Fatalf("after the catch-up = %v to %v", got.CurrentPeriodStart, got.CurrentPeriodEnd)
	}
	invs := e.Store.ListInvoices(e.Acme.ID, store.InvoiceFilter{SubscriptionID: sub.ID})
	if len(invs) != 3 {
		t.Fatalf("invoices = %d, want one per period (the first, Feb 28 to Mar 31, Mar 31 to Apr 30)", len(invs))
	}
	want := []struct{ start, end time.Time }{
		{time.Date(2026, 1, 31, 10, 0, 0, 0, time.UTC), time.Date(2026, 2, 28, 10, 0, 0, 0, time.UTC)},
		{time.Date(2026, 2, 28, 10, 0, 0, 0, time.UTC), time.Date(2026, 3, 31, 10, 0, 0, 0, time.UTC)},
		{time.Date(2026, 3, 31, 10, 0, 0, 0, time.UTC), time.Date(2026, 4, 30, 10, 0, 0, 0, time.UTC)},
	}
	for i, w := range want {
		if invs[i].PeriodStart == nil || invs[i].PeriodEnd == nil || !invs[i].PeriodStart.Equal(w.start) || !invs[i].PeriodEnd.Equal(w.end) {
			t.Errorf("invoice %d covers %v to %v, want %v to %v", i, invs[i].PeriodStart, invs[i].PeriodEnd, w.start, w.end)
		}
	}
}

