162	// renew brings a subscription up to date: for each period that has ended by now, in order, it starts the next period and
163	// invoices it (a licensed plan) or the period that ended (a metered plan). Each period is saved before the next one is
164	// renewed, so a failure leaves the periods before it renewed.
165	func (s *Service) renew(ctx context.Context, sub store.Subscription, now time.Time) error {
166		plan, ok := s.Store.Plan(sub.OrgID, sub.PlanID)
167		if !ok {
168			return store.ErrNotFound
169		}
170		anchor := billing.Anchor(sub)
171		for !sub.CurrentPeriodEnd.After(now) {
172			if sub.CancelAtPeriodEnd {
173				end := sub.CurrentPeriodEnd
174				canceled, err := s.Store.UpdateSubscription(sub.OrgID, sub.ID, func(x *store.Subscription) error {
175					x.Status, x.CanceledAt = store.Canceled, &end
176					return nil
177				})
178				if err == nil {
179					s.publish(ctx, sub.OrgID, "subscription.canceled", canceled)
180				}
181				return err
182			}
183			start := sub.CurrentPeriodEnd
184			n := billing.PeriodIndex(anchor, plan.Interval, start)
185			end := billing.PeriodStart(anchor, plan.Interval, n+1)
186			paid := true
187			var err error
188			switch {
189			case plan.UsageType == store.Metered && sub.Status != store.Trialing:
190				paid, err = s.invoicePeriod(ctx, sub, plan, sub.CurrentPeriodStart, sub.CurrentPeriodEnd)
191			case plan.UsageType == store.Licensed:
192				paid, err = s.invoicePeriod(ctx, sub, plan, start, end)
193			}
194			if err != nil {
195				return err
196			}
197			updated, err := s.Store.UpdateSubscription(sub.OrgID, sub.ID, func(x *store.Subscription) error {
198				x.CurrentPeriodStart, x.CurrentPeriodEnd = start, end
199				if paid {
200					x.Status = store.Active
201				} else {
202					x.Status = store.PastDue
203				}
204				return nil
205			})
206			if err != nil {
207				return err
208			}
209			sub = updated
210			s.publish(ctx, sub.OrgID, "subscription.updated", sub)
211		}
212		return nil
213	}
