216	// It reports false when the charge was declined. An invoice that needs no charge is marked paid; one whose customer has no
217	// payment method stays open and counts as paid here (it is paid by hand).
218	func (s *Service) invoicePeriod(ctx context.Context, sub store.Subscription, plan store.Plan, start, end time.Time) (bool, error) {
219		var lines []store.Line
220		period := start.Format("Jan 2, 2006") + " to " + end.Format("Jan 2, 2006")
221		switch plan.UsageType {
222		case store.Licensed:
223			if plan.UnitAmount > 0 {
224				lines = append(lines, store.Line{Description: plan.Name + ", " + period, Quantity: int64(sub.Quantity), UnitAmount: plan.UnitAmount})
225			}
226		case store.Metered:
227			if used := s.Store.UsageTotal(sub.OrgID, sub.ID, start, end); used > 0 {
228				lines = append(lines, store.Line{Description: plan.Name + " usage, " + period, Quantity: used, UnitAmount: plan.UnitAmount})
229			}
230		}
231		ps, pe := start, end
232		inv, err := s.Store.CreateInvoice(store.Invoice{OrgID: sub.OrgID, CustomerID: sub.CustomerID, SubscriptionID: sub.ID, Currency: plan.Currency,
233			Lines: lines, DiscountPercent: sub.DiscountPercent, PeriodStart: &ps, PeriodEnd: &pe}, s.Clock.Now())
234		if err != nil {
235			return false, err
236		}
237		s.publish(ctx, sub.OrgID, "invoice.created", map[string]any{"invoice_id": inv.ID, "subscription_id": sub.ID})
238		_, _, err = s.Payments.Pay(ctx, sub.OrgID, inv.ID, "")
239		var decline *payments.DeclineError
240		switch {
241		case err == nil, errors.Is(err, payments.ErrNoPaymentMethod):
242			return true, nil
243		case errors.As(err, &decline):
244			return false, nil
245		default:
246			return false, err
247		}
248	}
